(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--ze-sj-prepa-sp-j1-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"ze-sj-prepa-sp-j1-idesfm\",\n \"titre\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 50,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n   \"sha256\": \"93fa9bef7cf4d39771263e2b4ecb3c21f3b1325dcee70c31c0d3d1b8c4f147be\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Santé publique · Prépa D.E J1 (IDE/SFM)\",\n     \"slug\": \"prepa-sp-j1-idesfm\",\n     \"pages\": \"\",\n     \"count\": 50,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Santé publique\",\n     \"source\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Disposer d'une margelle de 0,70 m de hauteur est une précaution à prendre pour l'aménagement d'un puits traditionnel.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le puits traditionnel doit avoir une margelle de 0,70 mètre de hauteur pour éviter les chutes des enfants et des animaux. Remarque : Le sujet écrit « 0,70 cm » : coquille probable pour 0,70 m.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, VIII. Précautions pour l'aménagement d'un puits traditionnel (p. 68)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'évaluation initiale permet de décrire les facteurs de risque de la population.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'évaluation initiale (analyse situationnelle) collecte les données nécessaires pour planifier ; elles décrivent les besoins de la population, les facteurs de risque, le contexte et les ressources disponibles.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Suivi-évaluation, 3.2.1 Évaluation initiale (p. 59)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La contre-référence est le retour du patient dans l'établissement sanitaire de premier contact d'origine pour la poursuite de son traitement.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La contre-référence est le retour du patient dans l'établissement sanitaire de premier contact d'origine pour la poursuite de son traitement.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Référence/contre-référence, 1.2 (p. 20)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La population cible primaire dans une action de santé est la personne ou le groupe qui doit agir.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La population cible primaire est la personne ou le groupe de personnes qui doivent changer de comportement (donc agir) pour que le programme atteigne son objectif. La cible secondaire influence ses décisions ; la cible tertiaire regroupe les décideurs et financiers. Remarque : Le cours dit « qui doivent changer de comportement » ; le sujet dit « qui doit agir ».\\n\\nSource : Document révisé L2 2023-2024 validé, Populations cibles de la CCSC (p. 7)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Faire la vaccination en stratégie avancée est une solution pour réduire les populations hors de portée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La stratégie avancée rapproche la vaccination des populations éloignées du centre de santé.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, 1.2-1.3 (p. 6) ; monitorage, tableau des goulots (p. 77)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Tous les membres du COGES sont issus de la communauté.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Outre l'infirmier, la sage-femme ou le travailleur social, les autres membres sont issus de la communauté : tous ne sont donc pas des membres communautaires.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, III. Composition (p. 23)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le VAP fait partie des vaccins concernés par la politique du flacon entamé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La politique du flacon entamé permet de réutiliser un flacon multidose liquide ouvert jusqu'à 4 semaines, sous conditions (non périmé, non contaminé, PCV non virée…).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, 6.7 La politique du flacon entamé (p. 17)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'évaluation initiale dans l'exécution d'un projet est aussi appelée analyse situationnelle.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours nomme explicitement l'évaluation initiale « analyse situationnelle ».\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Suivi-évaluation, 3.2.1 Évaluation initiale (Analyse situationnelle) (p. 59)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La surveillance passive nécessite des équipes qui recherchent activement les cas.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La surveillance passive repose sur la déclaration spontanée des cas par les professionnels ou les citoyens. C'est la surveillance active qui mobilise des équipes allant rechercher les cas sur le terrain.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Surveillance épidémiologique, 3.1-3.2 (p. 86-87)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le plaidoyer peut contribuer à réduire les inégalités en santé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Parmi les buts du plaidoyer figurent l'amélioration de l'accès aux soins et la réduction des inégalités en matière de santé.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Plaidoyer, II. Buts (p. 104)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La santé communautaire vise la promotion de la santé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La santé communautaire, fondée sur la participation et la mobilisation des communautés, est l'un des piliers de la promotion de la santé.\\n\\nSource : Document Santé publique L1 2021, 1.4 Santé communautaire (p. 7)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le superviseur ayant le style autocratique délègue les responsabilités.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le superviseur autocratique cherche à tout voir et tout contrôler : il ne délègue pas de responsabilité et surveille de près l'exécution des tâches.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Supervision, 4.1 Le style autocratique (p. 49)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les déchets biomédicaux doivent être éliminés dans des boîtes de sécurité.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La boîte de sécurité sert à recueillir les seringues, aiguilles et autres objets piquants ou tranchants souillés, pas l'ensemble des déchets biomédicaux.\\n\\nSource : Cours de santé publique, 5.6 Matériel de sécurité des injections (p. 66)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le budget aide à prioriser les dépenses sanitaires.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La budgétisation permet de suivre recettes et dépenses et d'accroître l'efficacité du centre par la priorisation dans le financement des activités.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Budgétisation, Conclusion (p. 19)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La PCV (pastille de contrôle du vaccin) est placée sur l'étiquette des vaccins liquides.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La PCV est placée sur l'étiquette des flacons de vaccin liquide, et sur la fermeture en plastique des flacons de vaccin en poudre (à reconstituer).\\n\\nSource : Document révisé L2 2023-2024 validé, X. La pastille de contrôle des vaccins (p. 39)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les maladies suivantes, indiquez les trois qui sont sous surveillance en Côte d'Ivoire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Choléra\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Paludisme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Fièvre hémorragique virale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Dracunculose\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Infections respiratoires aiguës\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Infections urinaires\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. Choléra ; C. C. Fièvre hémorragique virale ; D. D. Dracunculose\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Les maladies prioritaires sous surveillance comprennent les maladies à potentiel épidémique (choléra, fièvre hémorragique virale…) et les maladies visées par l'élimination ou l'éradication (ver de Guinée = dracunculose).\\n\\nSource : Document révisé L2 2023-2024 validé, SIMR, III. Maladies prioritaires sous surveillance (p. 71)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, identifiez les deux catastrophes naturelles.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. La guerre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Le cyclone\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Le tsunami\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. L'accident de circulation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Le cyclone ; C. C. Le tsunami\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Le cours cite les cyclones, les tremblements de terre et les tsunamis parmi les catastrophes naturelles. La guerre et l'accident de circulation sont causés par l'homme.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des catastrophes, IV. Types de catastrophes naturelles (p. 43)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, donnez les indicateurs permettant de mesurer l'ampleur d'un problème de santé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Taux de létalité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Taux d'incidence\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Taux de mortalité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Taux de prévalence\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Taux d'incidence ; D. D. Taux de prévalence\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Les taux d'incidence et de prévalence permettent d'évaluer l'ampleur d'une maladie dans une population. Le taux de létalité, lui, mesure la gravité.\\n\\nSource : Document révisé L2 2023-2024 validé, Épidémiologie, 3.2.2-3.2.3 et 3.2.6 (p. 32-33)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, indiquez les deux supports d'information individuelle.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Carnet de santé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Fiches de rapport de morbidité quotidienne, hebdomadaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Fiche de référence et de contre-référence\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Fiche de rapport mensuel et annuel\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. Carnet de santé ; C. C. Fiche de référence et de contre-référence\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Les supports d'information individuelle sont le carnet de santé, la fiche de référence et de contre-référence, la fiche de PF, la fiche de CPN… Les fiches de morbidité et les rapports mensuels/annuels sont des outils collectifs.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Information sanitaire, 5.1 Supports d'information individuelle (p. 39)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La promptitude des rapports signifie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. L'exactitude des données\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. L'envoi des rapports dans les délais requis\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La destruction des rapports\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Le nombre de registres disponibles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. L'envoi des rapports dans les délais requis\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La promptitude est le fait que les rapports soient reçus au plus tard à la date limite fixée, c'est-à-dire dans le délai requis.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 2.3.1 Promptitude des rapports (p. 30)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Parmi les activités suivantes à mener au CSU de Zaranou, indiquez les deux qui concernent la prévention.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. La vaccination\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Le fait de dormir sous moustiquaire imprégnée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La sensibilisation de la population\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Les pansements de plaies\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. La vaccination ; B. B. Le fait de dormir sous moustiquaire imprégnée\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"La vaccination est l'exemple type de prévention primaire, comme le fait de dormir sous moustiquaire imprégnée (lutte contre le risque avant la maladie). Les pansements relèvent du curatif. Remarque : La sensibilisation relève plutôt de la promotion de la santé.\\n\\nSource : Cours de santé publique, 1.10 Prévention (p. 9)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Parmi les fiches de rapport suivantes, indiquez celles qui vous serviront à gérer l'information sanitaire au CSU de Zaranou.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Fiche A1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Fiche B1\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Fiche A3\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Fiche B2\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Fiche D1\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. Fiche A1 ; C. C. Fiche A3\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Un centre de santé (ESPC) transmet un rapport mensuel de type A et un rapport annuel A3. Les fiches B1/B2 concernent l'hôpital général, la D1 le district. la correction nationale de la Prépa DE (les J) retient A1 et A3. Remarque : Le cours nomme le rapport mensuel de l'ESPC « A » ; le sujet écrit « A1 ».\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Information sanitaire, tableau des types de rapports (p. 30)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Donnez le nombre de fiches de rapport mensuel à commander pour vos activités de 2022 au CSU de Zaranou.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 24\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 20\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 12\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 10\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 20\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Prise de service le 04/03/2022 : 10 mois d'activité (mars à décembre). Les rapports mensuels se remplissent en double exemplaire (un envoyé, un archivé) : 10 × 2 = 20 fiches.\\n\\nSource : DOC-20260911-WA0542, 3.1.1 Au niveau des structures de prestations (p. 33)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Combien de fiches de rapport d'activités mensuelles devrez-vous archiver au CSU de Zaranou en 2022 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 24\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 20\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 12\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 10\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. 10\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Une copie de chaque rapport mensuel transmis reste dans les archives du centre : 10 mois = 10 fiches.\\n\\nSource : DOC-20260911-WA0542, 3.1.1 (p. 33) ; Cours Santé publique L1, L2, L3 révisé 2025-2026, archivage des rapports (p. 41)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quel est le rythme des activités de monitorage en Côte d'Ivoire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Mensuel\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Trimestriel\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Semestriel\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. Semestriel\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le monitorage porte sur une période de 6 mois : il est semestriel (la population cible annuelle est divisée par 2).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Monitorage, 4.1 La population cible (p. 72)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quelle est la période qui correspond au monitorage réalisé en décembre 2022 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 01/07/2022 au 31/12/2022\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 01/06/2022 au 30/11/2022\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 01/12/2022 au 31/05/2023\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 01/06/2022 au 30/11/2022\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un monitorage réalisé en décembre porte sur les six mois écoulés : du 1er juin au 30 novembre (exemple du cours : monitorage du 1er juin au 30 novembre 2024).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Monitorage, 4.1 (p. 72)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quelle est la durée de la période monitorée en décembre 2022 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 181 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 182 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 183 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 183 jours\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Juin 30 + juillet 31 + août 31 + septembre 30 + octobre 31 + novembre 30 = 183 jours.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Monitorage, 4.1 (p. 72) ; calcul de calendrier\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quel est le taux d'accroissement annuel de la population de l'aire sanitaire du CSU de Zaranou ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 0,025 %\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 2,50 %\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 2,49 %\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 0,024\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 2,49 %\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"TAA = (population d'arrivée – population de départ) / population de départ × 100 = (60 142 – 58 676) / 58 676 × 100 = 2,498 %. Remarque : Le calcul exact donne 2,498 % ; la correction nationale de la Prépa DE (les J) retient 2,49 % (valeur tronquée).\\n\\nSource : Document révisé L2 2023-2024 validé, 3.1.6 Taux d'accroissement annuel (p. 30)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quelle est la population totale de l'aire sanitaire du CSU de Zaranou en 2022 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 61 638 habitants\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 60 142 habitants\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 61 640 habitants\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 61 640 habitants\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Pt = P0 × (1 + r)^t = 60 142 × (1 + 0,0249) ≈ 61 640 habitants : la population du 01/01/2022 est projetée sur l'année 2022.\\n\\nSource : Document révisé L2 2023-2024 validé, Équation de projection démographique (p. 30)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quel est le taux brut de morbidité pour l'année 2022 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 9,02 ‰\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 9,13 ‰\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 9,24 ‰\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 9,13 ‰\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Taux brut de morbidité = nombre de cas de maladie de l'année / population de la même année × 1 000, soit 9,13 ‰ avec les données du tableau de l'étude de cas. Remarque : Le tableau de données de l'étude de cas n'est pas reproduit dans le document : le calcul ne peut pas être refait ici.\\n\\nSource : Document révisé L2 2023-2024 validé, Épidémiologie, indicateurs de morbidité (p. 31-32)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quel est l'effectif des enfants à vacciner en routine en 2022 dans l'aire sanitaire du CSU de Zaranou ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 4204 enfants\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 4202 enfants\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 4102 enfants\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. 4204 enfants\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En routine, la cible du PEV est l'enfant de 0 à 23 mois : 6,82 % de la population totale. 61 640 × 6,82 % ≈ 4 204 enfants.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, tableau n°1 Populations cibles du PEV (p. 7)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quel est l'effectif de la population cible de l'activité de monitorage de la vaccination de décembre 2022 au CSU de Zaranou ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 2051 enfants\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 2102 enfants\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 2101 enfants\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 2102 enfants\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La population cible du monitorage (6 mois) est la cible annuelle divisée par 2 : 4 204 / 2 = 2 102 enfants.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Monitorage, 4.1 La population cible (p. 72)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quelle est la période qui correspond à la budgétisation du monitorage réalisé en décembre 2022 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 01/07/2022 au 31/12/2022\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 01/06/2022 au 30/11/2022\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 01/12/2022 au 31/05/2023\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 01/12/2022 au 31/05/2023\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le budget établi lors du monitorage de décembre 2022 porte sur le semestre suivant : du 01/12/2022 au 31/05/2023. Remarque : Le découpage exact de la période budgétisée n'est pas écrit dans le cours (explication partiellement hors cours du projet).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Budgétisation des ressources propres (p. 16-19)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quel est le montant des recettes annuelles du CSU de Zaranou ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 3 240 000 F\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 1 440 000 F\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 1 500 000 F\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 1 440 000 F\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les recettes annuelles du CSU sont de 1 440 000 F d'après le tableau de l'étude de cas. Remarque : Le tableau de données de l'étude de cas n'est pas reproduit dans le document.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, IV. Ressource propre d'un ESPC (p. 16)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quel est le montant des ressources propres enregistrées par le CSU de Zaranou ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 825 000 F\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 1 782 000 F\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 792 000 F\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 792 000 F\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Ressources propres = recettes brutes – (FAS 10 % + IP 15 % + SPS 20 %) = 1 440 000 – 648 000 = 792 000 F (soit 55 % des recettes).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, IV. Ressource propre d'un ESPC (p. 16) ; Formules santé publique harmonisées, §7 (p. 6)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quel est le montant des dépenses du CSU de Zaranou ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 648 000 F\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 1 458 000 F\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 675 000 F\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. 648 000 F\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Total des dépenses du centre = FAS (10 %) + IP (15 %) + SPS (20 %) = 45 % des recettes brutes : 45 % × 1 440 000 = 648 000 F.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, IV. Ressource propre d'un ESPC (p. 16)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quel est l'écart entre l'objectif vaccinal en VPO et celui réellement atteint par l'aire sanitaire du CSU de Zaranou en 2022 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 5 %\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 10 %\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 25 %\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 25 %\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Écart = objectif vaccinal – couverture réellement atteinte (objectif de 95 % en VPO), soit 25 % avec les données du tableau de l'étude de cas. Remarque : Le tableau de données de l'étude de cas n'est pas reproduit dans le document.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, tableau n°2 Objectifs vaccinaux (p. 8)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Quel est le taux de perte en Penta enregistré par le personnel de l'aire sanitaire du CSU de Zaranou en 2022 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 10 %\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 20 %\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 30 %\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 20 %\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Taux de perte = (doses sorties – doses administrées) / doses sorties × 100, soit 20 % avec les données du tableau de l'étude de cas. Remarque : Le tableau de données de l'étude de cas n'est pas reproduit dans le document.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, formule du taux de perte (p. 10)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — Après l'inauguration du Centre de Santé Urbain (CSU) de Zaranou le 28 janvier 2022, vous avez pris service le 04 mars 2022 pour mener les activités de soins de santé. La population de l'aire sanitaire a été estimée à 58 676 habitants au 31/12/2020 et à 60 142 habitants au 01/01/2022. En décembre 2022, le Directeur départemental entreprend une activité de monitorage ayant pour principale difficulté le fonctionnement de votre structure, couplée à une évaluation des activités de l'année 2022. Les principales données collectées figurent dans un tableau (non reproduit dans le document source).\",\n       \"text\": \"Calculez le facteur de perte en Penta de l'aire sanitaire du CSU de Zaranou en 2022.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 1,05\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 1,11\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 1,25\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 1,42\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 1,25\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"FP = 100 / (100 – taux de perte) = 100 / (100 – 20) = 1,25.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, formule du facteur de perte (p. 10)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Le nombre d'enfants de 0 à 23 mois de l'aire sanitaire du CSU de Zaranou est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 2000 enfants\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 20 105 enfants\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 2405 enfants\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 4102 enfants\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. 4102 enfants\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Enfants de 0 à 23 mois = 6,82 % de la population totale : 60 142 × 6,82 % ≈ 4 102 enfants.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, tableau n°1 (p. 7)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Quel est le besoin théorique annuel en vaccin RR, exprimé en doses ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 4326 doses\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 4560 doses\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 8652 doses\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 9119 doses\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. 9119 doses\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"BT annuel = cible × objectif vaccinal × nombre de contacts × FP = 4 102 × 95 % × 2 (RR1, RR2) × 1,17 ≈ 9 119 doses.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, tableaux n°2 et n°3, FP RR = 1,17, 3.1.1.1 Besoin annuel (p. 8-11)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Quel est le besoin théorique annuel en seringues injectables ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 4326 seringues\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 4560 seringues\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 8652 seringues\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 9119 seringues\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 8652 seringues\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Seringues : même calcul avec le facteur de perte des seringues (1,11) : 4 102 × 95 % × 2 × 1,11 ≈ 8 652 seringues.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.2.1 Commande des seringues autobloquantes (p. 12)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Quel est le stock de sécurité (SS) du vaccin RR, exprimé en doses ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 2280 doses\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 1082 doses\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 1140 doses\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 2163 doses\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. 2280 doses\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Stock de sécurité des vaccins = 25 % du BT : 9 119 × 25 % ≈ 2 280 doses.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.1.2 Le stock de sécurité en vaccin (p. 11)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Quel est le stock de sécurité (SS) des seringues injectables ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 456 seringues\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 433 seringues\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 912 seringues\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 866 seringues\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. 866 seringues\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Stock de sécurité des consommables = 10 % du BT : 8 652 × 10 % ≈ 866 seringues (arrondi supérieur).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.2.1 (p. 12)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Quel est le besoin réel (BR) du vaccin RR, exprimé en doses ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 9792 doses\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 11 399 doses\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 6606 doses\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 5642 doses\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 11 399 doses\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"BR = BT + SS = 9 119 + 2 280 = 11 399 doses.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.1.3 Le besoin réel (p. 11)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Quel est le besoin réel (BR) en seringues injectables ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 9518 seringues\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 5016 seringues\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 4782 seringues\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 4759 seringues\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. 9518 seringues\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"BR = BT + SS = 8 652 + 866 = 9 518 seringues.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.1.3 et 3.2.1 (p. 11-12)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Avant la commande, le stock était de 180 doses de vaccin RR (flacons de 10 doses), 300 seringues injectables et 140 seringues de dilution. Quelle est la prévision en vaccin RR, exprimée en doses, pour l'année 2023 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 11 219 doses\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 9612 doses\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 6426 doses\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 5462 doses\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. 11 219 doses\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Prévision (quantité à commander) = BR – quantité en stock = 11 399 – 180 = 11 219 doses.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.1.4 La quantité à commander (p. 11)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Quelle est la quantité à commander (QC) de seringues injectables pour l'année 2023 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 4459 seringues\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 4482 seringues\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 4716 seringues\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 9218 seringues\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D. 9218 seringues\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"QC = BR – QS = 9 518 – 300 = 9 218 seringues injectables.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.1.4 (p. 11)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Quelle est la quantité à commander (QC) de seringues de dilution pour l'année 2023 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 643 seringues de dilution\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 1122 seringues de dilution\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 1000 seringues de dilution\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 547 seringues de dilution\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 1000 seringues de dilution\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Il faut une seringue de dilution par flacon : 11 399 doses / 10 ≈ 1 140 flacons, moins les 140 seringues de dilution en stock = 1 000. Remarque : L'option B (1 122) correspond à 11 219 / 10 sans déduire le stock de seringues de dilution.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.2.2 Commande des seringues à dilution (p. 12)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j1-idesfm__49\",\n       \"num\": \"50\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — Vous avez été nouvellement affecté(e) au CSU de Zaranou (district sanitaire d'Abengourou) le 03 janvier 2023. Le médecin-chef vous nomme responsable du service de vaccination en remplacement de l'infirmier admis à son concours professionnel. Il vous demande d'estimer les besoins en vaccin RR et en seringues, sachant que la population totale de l'aire sanitaire est estimée à 60 142 habitants pour 2023.\",\n       \"text\": \"Quelle est la quantité de boîtes de sécurité à commander pour l'année 2023 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 104 boîtes de sécurité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 103 boîtes de sécurité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 57 boîtes de sécurité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. 98 boîtes de sécurité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 103 boîtes de sécurité\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une boîte de sécurité contient environ 100 seringues : (9 218 seringues injectables + 1 000 seringues de dilution) / 100 = 102,2, arrondi à 103 boîtes.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.2.3 Commande des boîtes de sécurité (p. 12)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Santé publique IDE/SFM\",\n       \"sourceFile\": \"J1_SANTE_PUBLIQUE_IDE_SFM_corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
